import { defineLesson, type LessonDraft } from "../authoring";
import type { Question } from "../types";
type Draft = Omit<LessonDraft, "questions"> & { questions: Omit<Question, "id">[] };
const unit = (draft: Draft) => defineLesson(12, { ...draft, questions: draft.questions.map((question, index) => ({ ...question, id: `${draft.slug}-${index + 1}` })) });
const section = (id: string, title: string, text: string) => ({ id, title, paragraphs: [text] });
const plan = { title: "CME Group: plan y gestión del riesgo", url: "https://www.cmegroup.com/education/courses/building-a-trade-plan/risk-management-and-your-trade-plan", note: "Material educativo oficial. Las rutinas y presupuestos propuestos son ejercicios originales, no recomendaciones de operar." };
const demo = { title: "CFTC: sistemas y resultados hipotéticos", url: "https://www.cftc.gov/LearnAndProtect/AdvisoriesAndArticles/fraudadv_tradingsystem.html", note: "Límites de resultados simulados y de afirmaciones comerciales sobre sistemas." };

export const level12Lessons = [
  unit({ slug: "rutina-profesional-y-calidad-de-decision", title: "Rutina profesional y calidad de decisión", subtitle: "La preparación se demuestra en registros y controles, no en actividad constante.",
    objectives: ["Organizar preparación, sesión y revisión", "Evaluar decisiones sin sesgo de resultado", "Definir condiciones de descanso y abstención"], prerequisites: ["Plan documentado y psicología"],
    sections: [
      section("rutina", "Una rutina protege la coherencia", "Preparar una sesión significa comprobar datos, calendario, reglas y capacidad personal para seguir el procedimiento. La rutina debe ser compatible con la vida cotidiana y con el horizonte del sistema. No necesitas observar gráficos continuamente para aprender ni para justificar una jornada productiva. Define tareas concretas y sus resultados verificables: datos validados, presupuesto actualizado o incidencias revisadas. Si una condición crítica falta, la sesión puede limitarse a estudio o mantenimiento. Una práctica profesional consiste en respetar ese límite incluso cuando una imagen del mercado parece atractiva y otras personas publican operaciones que generan presión por participar."),
      section("decision", "Proceso y resultado no son sinónimos", "Una decisión se evalúa con la información disponible cuando se tomó, las reglas aceptadas y la calidad de su ejecución. El resultado posterior añade información sobre el sistema, pero no reescribe lo que era razonable conocer. Una operación ganadora que incumple un límite puede reforzar un hábito peligroso si solo celebras el dinero ficticio obtenido. Una pérdida correctamente ejecutada puede ser parte de la distribución prevista. Utiliza dos columnas separadas: cumplimiento y resultado. Esta separación no absuelve reglas deficientes; permite revisar la estrategia con evidencia agregada mientras corriges incumplimientos concretos sin confundir ambos problemas."),
      section("carga", "Fatiga, atención y condiciones de abstención", "La calidad del seguimiento puede deteriorarse cuando se acumulan cansancio, interrupciones o deseo de recuperar pérdidas. Define señales personales observables para pausar: errores repetidos de cantidad, omisión de controles o incapacidad de explicar la siguiente acción prevista. No conviertas un cuestionario emocional en un diagnóstico clínico ni en una garantía de autocontrol. Su función es facilitar una decisión prudente dentro del plan. Reserva descansos y un límite de tiempo de pantalla. La racha educativa debe premiar estudio y revisión, no número de operaciones; abrir más posiciones para mantener una etiqueta contradice el propósito de gestionar riesgo y aprender."),
      section("revision", "Cerrar la jornada con una mejora concreta", "La revisión diaria debe reconciliar registros, identificar incidencias y proponer acciones limitadas. Cambiar todos los parámetros tras una mala sesión impide acumular evidencia comparable. Distingue correcciones técnicas urgentes de decisiones de investigación que esperan una revisión programada. Formula una mejora comprobable, como registrar siempre la zona horaria, y verifica después su cumplimiento. Conserva también días sin señales y decisiones de no actuar. Una rutina profesional no elimina incertidumbre ni convierte la simulación en ingresos. Su valor es reducir errores evitables, hacer visible el proceso y permitir que una evaluación posterior atribuya resultados a reglas conocidas en lugar de recuerdos selectivos."),
    ], workedExample: { title: "Evaluación simulada del proceso", scenario: "En 12 decisiones registradas, 10 cumplen el plan. De las dos excepciones, una gana y otra pierde.", steps: ["Cumplimiento: 10/12×100 ≈ 83,33 %.", "Ambas excepciones siguen siendo incumplimientos, independientemente del beneficio.", "Se revisan las causas sin reclasificar la excepción ganadora como decisión correcta."], conclusion: "El porcentaje describe disciplina del registro; no expresa rentabilidad ni una licencia profesional." },
    commonMistakes: [{ mistake: "Juzgar disciplina solo por dinero ganado", correction: "Evalúa reglas y desenlace en columnas separadas." }, { mistake: "Operar para mantener una racha", correction: "Usa estudio, revisión y abstención documentada como actividad válida." }], summary: ["La rutina incluye abstenerse.", "Separa cumplimiento y resultado.", "Mejora el proceso con acciones verificables."], relatedConcepts: ["Sesgo de resultado", "Disciplina"], sources: [plan], diagram: { title: "Ciclo de una sesión", nodes: ["Preparación", "Controles críticos", "Decisiones o abstención", "Conciliación", "Una mejora comprobable"], caption: "La actividad educativa no exige abrir posiciones." },
    questions: [
      { type: "number", concept: "Cumplimiento", prompt: "10 decisiones regladas entre 12 representan ¿qué porcentaje?", answer: 83.3333, tolerance: 0.01, required: true, explanation: "10/12×100≈83,33 %." },
      { type: "choice", concept: "Calidad de decisión", prompt: "Una excepción ganó. ¿Cómo se clasifica respecto al plan?", options: ["Como incumplimiento con resultado favorable", "Como cumplimiento automático", "Como prueba definitiva de una regla nueva"], answer: "Como incumplimiento con resultado favorable", explanation: "El desenlace no cambia las condiciones bajo las que se decidió." },
      { type: "boolean", concept: "Rutina", prompt: "Una jornada sin operaciones puede ser correcta y educativa.", options: ["Verdadero", "Falso"], answer: "Verdadero", explanation: "Preparación, estudio y abstenciones justificadas forman parte del proceso." },
      { type: "text", concept: "Sesgo", prompt: "Juzgar una decisión solo por cómo terminó es sesgo de…", answer: "resultado", explanation: "La evaluación debe considerar la información disponible al decidir." },
    ],
  }),
  unit({ slug: "plan-de-negocio-costes-y-reservas", title: "Plan de actividad, costes y reservas", subtitle: "Un presupuesto separa gastos ciertos de ingresos inciertos.",
    objectives: ["Clasificar costes fijos y variables", "Calcular un umbral contable", "Distinguir capital experimental y necesidades personales"], prerequisites: ["Costes y esperanza neta"],
    sections: [
      section("presupuesto", "El presupuesto empieza por lo conocido", "Un proyecto de aprendizaje puede tener gastos de datos, software, formación, conectividad y mantenimiento. Clasifica cuáles son necesarios y cuáles opcionales antes de contratar nada. Las funciones educativas de esta academia no requieren pagar un proveedor externo para estudiar y corregir ejercicios. Un plan de actividad enumera gastos previstos, tiempo dedicado y objetivos verificables. No convierte una curva simulada en un sueldo mensual. Los gastos contractuales pueden llegar aunque no haya oportunidades, mientras que los ingresos de trading son inciertos y pueden ser negativos. Esa asimetría debe aparecer de forma explícita en cualquier presupuesto responsable."),
      section("costes", "Separar coste fijo y coste por operación", "Un coste fijo se mantiene durante el periodo definido aunque no operes; uno variable cambia con actividad, cantidad o duración de posiciones. La financiación nocturna, comisiones y conversiones pueden seguir reglas diferentes. Un análisis de punto de equilibrio divide gastos fijos entre contribución media neta de costes variables, siempre que esa contribución sea positiva y tenga una interpretación válida. Si utilizas una contribución hipotética, el resultado también es hipotético. No aumentes el número de operaciones para alcanzar mecánicamente ese umbral: hacerlo puede cambiar la calidad de señales y la distribución que suponías constante en la fórmula."),
      section("reservas", "No confundir reservas con capital disponible para riesgo", "El dinero necesario para vivienda, alimentación, impuestos u obligaciones no es equivalente a capital que puedas perder sin afectar necesidades esenciales. En un ejercicio de planificación puedes separar una reserva de gastos y un presupuesto educativo limitado. Esa clasificación ayuda a ver restricciones, pero no determina una cantidad adecuada para cada persona. Tampoco garantiza que una pérdida quede dentro de lo previsto. Incluye escenarios sin ingresos y costes imprevistos, y reconoce el coste de oportunidad del tiempo. La presión por pagar gastos con resultados inciertos puede inducir más riesgo precisamente cuando el capital y la atención son más vulnerables."),
      section("viabilidad", "Medir viabilidad sin vender una promesa", "Una revisión periódica compara gastos reales con presupuesto y resultados de aprendizaje con objetivos. Pregunta si una suscripción aporta datos necesarios o simplemente una sensación de profesionalidad. Registra cancelaciones, renovaciones y condiciones de devolución para evitar compromisos olvidados. Si una estrategia solo parece viable suponiendo ingresos regulares no demostrados, el plan todavía no respalda esa conclusión. Puedes decidir continuar estudiando con menor coste, cambiar el diseño o detener el proyecto. Ninguna de esas decisiones exige recuperar primero lo gastado: los costes hundidos no convierten una nueva compra o una operación adicional en una elección económicamente justificada."),
    ], workedExample: { title: "Umbral contable simulado", scenario: "Gastos fijos ficticios de 120 € al mes y contribución supuesta de 4 € por operación después de costes variables.", steps: ["Umbral aritmético: 120/4 = 30 operaciones.", "Si la contribución baja a 2 €, el umbral sería 60.", "Si la contribución es cero o negativa, más operaciones no cubren el gasto fijo mediante esta fórmula."], conclusion: "El cálculo no recomienda operar 30 veces ni demuestra que exista esa contribución media." },
    commonMistakes: [{ mistake: "Tratar beneficio demo como salario previsto", correction: "Modela ingresos inciertos y separa evidencia de supuestos." }, { mistake: "Operar más para cubrir suscripciones", correction: "No alteres reglas para perseguir un umbral contable." }], summary: ["Los gastos ciertos no dependen de ganar.", "Declara supuestos del punto de equilibrio.", "Los costes hundidos no justifican más riesgo."], relatedConcepts: ["Coste de oportunidad", "Punto de equilibrio"], sources: [plan, demo], diagram: { title: "Presupuesto ficticio", nodes: ["Coste fijo 120 €", "Contribución supuesta 4 €", "Umbral matemático 30", "Ingresos no garantizados", "Revisar viabilidad"], caption: "Un umbral aritmético no es un objetivo de frecuencia operativa." },
    questions: [
      { type: "number", concept: "Punto de equilibrio", prompt: "120 € fijos divididos entre 4 € de contribución hipotética dan…", answer: 30, tolerance: 0, required: true, explanation: "120/4=30; el supuesto no garantiza que existan esas oportunidades." },
      { type: "choice", concept: "Coste fijo", prompt: "¿Qué puede mantenerse aunque no abras operaciones?", options: ["Una suscripción mensual contratada", "Una comisión exclusivamente por operación", "El número de señales"], answer: "Una suscripción mensual contratada", explanation: "Su vencimiento depende del contrato, no del resultado del sistema." },
      { type: "boolean", concept: "Viabilidad", prompt: "Una media neta no positiva se arregla necesariamente operando más.", options: ["Verdadero", "Falso"], answer: "Falso", explanation: "Más actividad no cambia por sí sola una contribución negativa y puede aumentar costes." },
      { type: "text", concept: "Decisión económica", prompt: "Un gasto pasado que no puede recuperarse se denomina coste…", answer: "hundido", explanation: "La nueva decisión debe evaluarse por sus consecuencias futuras, no por recuperar a cualquier precio." },
    ],
  }),
  unit({ slug: "cuentas-demo-y-limites-de-la-practica", title: "Cuentas demo y límites de la práctica", subtitle: "Practicar sin dinero real permite aprender, pero no reproduce todos los riesgos de ejecución.",
    objectives: ["Definir objetivos de una prueba demo", "Identificar diferencias con una cuenta real", "Evitar conclusiones a partir de saldos reiniciados"], prerequisites: ["Forward testing y gestión del riesgo"],
    sections: [
      section("objetivo", "Elegir qué habilidad se está practicando", "Una cuenta demo puede servir para aprender órdenes, comprobar cálculos, ensayar un procedimiento y registrar decisiones sin comprometer capital real. Cada objetivo requiere una prueba distinta. Si estás aprendiendo la interfaz, puedes repetir una acción con datos artificiales; si evalúas disciplina prospectiva, debes conservar todo el historial y los errores. El saldo ficticio no mide patrimonio disponible ni capacidad de afrontar pérdidas. Define capital inicial, reglas y duración de la práctica antes de comenzar. Esa claridad evita confundir un ejercicio de familiarización con una evaluación de estrategia supuestamente comparable a una cuenta ejecutada en condiciones reales."),
      section("ejecucion", "La simulación depende de reglas del proveedor", "Una plataforma demo puede asignar ejecuciones con liquidez simplificada, retrasos distintos o ausencia de ciertos rechazos. El mercado real puede exigir condiciones diferentes para cantidades, margen y disponibilidad de precios. No presupongas equivalencia porque el gráfico tenga el mismo aspecto o porque ambos entornos muestren el mismo símbolo. Identifica qué precios recibe la demo y cómo aplica spread, financiación y comisiones. Si esos detalles no están disponibles, reconoce la limitación en el informe. Una ejecución perfecta observada en práctica solo demuestra que el entorno simulado la atribuyó, no que una operación real idéntica hubiera recibido necesariamente ese precio."),
      section("conducta", "Reinicios y tamaño ficticio cambian el experimento", "Reiniciar el saldo después de cada caída elimina información sobre rachas, recuperación y límites. Si necesitas un reinicio para un ejercicio específico, conserva el historial anterior y distingue claramente ambas sesiones. Usar un capital ficticio enorme también puede hacer irrelevantes errores de tamaño que serían importantes con otro presupuesto. Ajusta las cantidades al objetivo pedagógico y expresa resultados en unidades de riesgo cuando corresponda. La ausencia de dinero real puede cambiar tu respuesta emocional, por lo que cumplir reglas en demo no prueba cómo actuarías bajo presión financiera. Esa limitación no invalida el aprendizaje operativo; delimita lo que puedes concluir de él."),
      section("evidencia", "Qué evidencia sí puede aportar", "Una práctica bien registrada permite demostrar que sabes calcular riesgo, introducir una orden prevista, respetar una pausa y explicar resultados netos. También permite detectar fallos de la plataforma o de tu procedimiento antes de experimentar con sistemas más complejos. Revisa cumplimiento, omisiones y coherencia contable, además de beneficios y pérdidas ficticios. No uses una pequeña muestra positiva para asignarte una etiqueta de rentabilidad profesional. Las condiciones regulatorias y contractuales de un producto real se revisan por separado; disponer de una demo no acredita autorización para comercializarlo ni concede una protección legal que cubra de manera automática cualquier futura relación contractual."),
    ], workedExample: { title: "Reinicio que oculta una caída", scenario: "Una cuenta ficticia empieza en 5.000 €, cae a 4.500 € y después se reinicia a 5.000 €.", steps: ["Pérdida antes del reinicio: 500 €.", "Drawdown respecto al inicio: 500/5.000×100 = 10 %.", "El reinicio no elimina la pérdida del experimento anterior; crea otra sesión."], conclusion: "Mostrar solo el nuevo saldo ocultaría una parte relevante de la práctica." },
    commonMistakes: [{ mistake: "Borrar sesiones perdedoras y mostrar solo la mejor", correction: "Conserva todos los historiales y el motivo de cada reinicio." }, { mistake: "Confundir acceso a demo con garantía regulatoria", correction: "Verifica por separado entidad, producto y condiciones reales." }], summary: ["Define la habilidad que practicas.", "Documenta límites de ejecución demo.", "Conserva errores, pérdidas y reinicios."], relatedConcepts: ["Resultados hipotéticos", "Sesgo de selección"], sources: [demo, { title: "CFTC: educación sobre riesgos de Forex", url: "https://www.cftc.gov/LearnAndProtect/forexfrauds", note: "Distingue práctica y exposición a riesgos; no es normativa belga." }], diagram: { title: "Dos sesiones no son una curva continua", nodes: ["Inicio 5.000 €", "Caída a 4.500 €", "Drawdown 10 %", "Reinicio explícito", "Nueva sesión 5.000 €"], caption: "La sesión anterior permanece en el historial de aprendizaje." },
    questions: [
      { type: "number", concept: "Drawdown demo", prompt: "De 5.000 a 4.500 €, ¿qué caída porcentual hay?", answer: 10, tolerance: 0, required: true, explanation: "(5.000−4.500)/5.000×100=10 %." },
      { type: "choice", concept: "Reinicio", prompt: "Al reiniciar una demo después de perder corresponde…", options: ["Conservar la sesión anterior y etiquetar la nueva", "Borrar toda evidencia anterior", "Sumar el reinicio como beneficio"], answer: "Conservar la sesión anterior y etiquetar la nueva", explanation: "El reinicio es una modificación del experimento, no rendimiento de mercado." },
      { type: "boolean", concept: "Ejecución", prompt: "Una ejecución demo garantiza el mismo resultado de ejecución real.", options: ["Verdadero", "Falso"], answer: "Falso", explanation: "Liquidez, rechazos y otros supuestos pueden diferir." },
      { type: "text", concept: "Práctica", prompt: "¿Cómo deben describirse los beneficios obtenidos con dinero ficticio?", answer: "simulados", acceptedAnswers: ["hipotéticos", "hipoteticos", "ficticios"], explanation: "No deben presentarse como ingresos reales verificados." },
    ],
  }),
  unit({ slug: "cuentas-fondeadas-y-reglas-de-prop-firms", title: "Cuentas fondeadas y reglas de prop firms", subtitle: "Un nombre comercial no revela si operas capital real ni cómo se calculan tus derechos.",
    objectives: ["Distinguir capital anunciado y relación contractual", "Calcular límites estáticos y móviles", "Identificar costes y condiciones de remuneración"], prerequisites: ["Drawdown, demo y contratos"],
    sections: [
      section("modelo", "Identificar el servicio realmente ofrecido", "La expresión cuenta fondeada puede describir modelos comerciales diferentes y no prueba que una persona controle una cuenta real con el capital anunciado. La FSMA advirtió en marzo de 2024 sobre ofertas de desafíos pagados y prácticas de inversión simulada vinculadas a determinadas prop trading firms. Esa advertencia debe leerse en su contexto y no sustituye examinar una entidad concreta. Pregunta qué compras, quién es la contraparte, dónde se mantiene el registro y qué condiciones generan una remuneración. Un certificado emitido por la propia empresa no es por sí mismo una autorización regulatoria ni una acreditación de competencia reconocida por un supervisor."),
      section("limites", "Leer la fórmula exacta del drawdown", "Un límite puede ser estático respecto al capital inicial, diario respecto a una referencia que se reinicia, o móvil respecto a un máximo de balance o equity. Las palabras pérdida máxima son insuficientes sin fórmula. Comprueba si incluyen resultados abiertos, comisiones y financiación, qué reloj marca el cambio de día y si alcanzar el límite equivale a incumplirlo. Un máximo móvil puede subir con ganancias no realizadas y no bajar cuando estas desaparecen. Por ello, una operación que vuelve al precio de entrada podría vulnerar una barrera que parecía lejana si solo mirabas el balance al comienzo de la sesión."),
      section("costes", "El importe publicitado no es el presupuesto personal", "El riesgo económico del participante puede incluir cuota del desafío, renovaciones, reintentos y servicios adicionales. No confundas una cifra de capital nominal con dinero que puedes retirar. Lee condiciones de reparto, fechas de pago, restricciones de estrategias, noticias, posiciones nocturnas y posibles causas de exclusión. Si una condición no puede entenderse o comprobarse, esa incertidumbre forma parte de la evaluación del servicio. Las reglas pueden crear incentivos para asumir demasiado riesgo con tal de alcanzar un objetivo rápido. Superar un desafío bajo un conjunto de reglas tampoco demuestra que el procedimiento tenga ventaja estable ni que sea viable fuera de ese entorno."),
      section("evaluacion", "Evaluar sin convertir el desafío en un objetivo educativo", "La advertencia de FSMA destaca riesgos de costes, falta de claridad y comportamientos imprudentes en estos modelos. La academia no recomienda comprar desafíos ni conecta cuentas para ejecutarlos. Un ejercicio útil consiste en reconstruir por escrito escenarios de incumplimiento y obligaciones de ambas partes antes de considerar cualquier oferta. Conserva la versión de términos consultada y verifica identidad y autorización cuando se ofrezcan servicios de inversión. No atribuyas automáticamente a una relación de simulación o remuneración contractual las protecciones propias de una cuenta de inversión regulada. Si aparecen dudas legales sobre una oferta en Bélgica, consulta al supervisor por sus canales oficiales."),
    ], workedExample: { title: "Barrera móvil completamente simulada", scenario: "Regla ficticia: barrera=mayor equity alcanzada menos 5.000 unidades. La equity máxima sube de 100.000 a 103.000.", steps: ["Barrera inicial: 100.000−5.000 = 95.000.", "Nueva barrera: 103.000−5.000 = 98.000.", "Con equity actual de 100.000, el margen hasta la barrera es 2.000."], conclusion: "Es una regla inventada para enseñar el cálculo; cada contrato real puede definir otra fórmula." },
    commonMistakes: [{ mistake: "Interpretar capital nominal como saldo retirable", correction: "Lee derechos de remuneración y naturaleza de la cuenta." }, { mistake: "Usar balance cuando la barrera se calcula sobre equity", correction: "Reconstruye la fórmula exacta y su reloj." }], summary: ["Identifica el contrato, no solo el nombre.", "Calcula cada límite con su referencia.", "Incluye cuotas, reintentos y condiciones de pago."], relatedConcepts: ["Drawdown móvil", "Riesgo contractual"], sources: [{ title: "FSMA: advertencia sobre prop trading y simulación", url: "https://www.fsma.be/en/warnings/fsma-warns-consumers-against-shadow-investment-game", note: "Advertencia del 7/03/2024 consultada el 13/10/2026. Describe modelos y riesgos; verificar cada oferta concreta." }], diagram: { title: "Barrera móvil ficticia", nodes: ["Máximo 100.000", "Barrera 95.000", "Nuevo máximo 103.000", "Nueva barrera 98.000", "Equity 100.000: margen 2.000"], caption: "Ejemplo inventado, no condiciones de ninguna empresa." },
    questions: [
      { type: "number", concept: "Barrera móvil", prompt: "Máximo 103.000 menos distancia fija 5.000: ¿dónde queda la barrera?", answer: 98000, tolerance: 0, required: true, explanation: "103.000−5.000=98.000 bajo la regla ficticia especificada." },
      { type: "choice", concept: "Contrato", prompt: "¿Qué demuestra por sí solo un certificado emitido por una prop firm?", options: ["Solo lo que certifique su propio emisor, no autorización del supervisor", "Una autorización FSMA automática", "Rentabilidad futura garantizada"], answer: "Solo lo que certifique su propio emisor, no autorización del supervisor", explanation: "Una etiqueta comercial no sustituye una autorización verificable." },
      { type: "boolean", concept: "Capital nominal", prompt: "El capital anunciado de una cuenta fondeada es siempre dinero retirable por el participante.", options: ["Verdadero", "Falso"], answer: "Falso", explanation: "Los derechos dependen del contrato y de la naturaleza real o simulada del modelo." },
      { type: "text", concept: "Valoración", prompt: "Si un límite incluye pérdidas abiertas, ¿debes mirar solo balance o también equity?", answer: "equity", acceptedAnswers: ["también equity", "tambien equity"], explanation: "La equity incorpora resultados no realizados que pueden activar la barrera." },
    ],
  }),
  unit({ slug: "regulacion-belgica-ue-e-instrumentos", title: "Bélgica y UE: regulación e instrumentos", subtitle: "La protección y la comercialización dependen del producto, el cliente y la jurisdicción.",
    objectives: ["Distinguir contado, CFD y futuros", "Explicar el alcance publicado por FSMA", "Separar medidas europeas y nacionales"], prerequisites: ["Productos Forex y apalancamiento"],
    sections: [
      section("producto", "Clasificar antes de interpretar una norma", "Cambiar moneda para un pago no es el mismo contrato que especular sobre una diferencia de cotizaciones. Un CFD es un derivado cuyo resultado depende de diferencias de precio; un futuro tiene especificaciones y vencimientos de un mercado organizado; rolling spot puede ser un producto apalancado renovable y no debe confundirse automáticamente con entrega ordinaria de divisas. La etiqueta Forex de una página comercial no resuelve esa clasificación. Identifica obligaciones, contraparte, liquidación y lugar de negociación. Solo después puedes estudiar qué reglas de comercialización y protección corresponden; dos productos que muestran EUR/USD pueden quedar sujetos a condiciones jurídicas distintas."),
      section("belgica", "El alcance que publica FSMA", "La FAQ oficial de FSMA, verificada el 13 de octubre de 2026, describe una prohibición de distribución a consumidores mediante plataformas electrónicas de ciertos derivados OTC, incluidos derivados apalancados como CFD y rolling spot forex. También contempla determinadas técnicas de distribución inadecuadas. La misma FAQ delimita el alcance a instrumentos OTC y excluye de esa prohibición específica los negociados en mercado regulado o en un sistema multilateral operado por un gestor de mercado. No traduzcas esto como prohibición universal de cambiar divisas ni como afirmación de que cualquier futuro esté permitido sin otras condiciones. La norma trata una actividad de distribución concreta."),
      section("europa", "ESMA no sustituye el análisis nacional", "ESMA introdujo medidas temporales sobre CFD minoristas, con controles como límites de apalancamiento y protección de saldo negativo. En julio de 2019 comunicó que dejaría de renovarlas porque muchas autoridades nacionales habían adoptado medidas permanentes al menos igual de estrictas. Por tanto, citar una decisión temporal antigua sin revisar la medida nacional actual puede inducir a error. La protección de saldo negativo asociada al marco CFD se refiere a responsabilidad agregada de una cuenta cubierta por sus condiciones; no es seguro contra pérdidas de inversión ni una protección trasladable sin más a futuros, clientes profesionales o contratos de simulación comercial."),
      section("verificar", "Un procedimiento de verificación concreto", "Para analizar una oferta, escribe producto exacto, entidad jurídica, país desde el que se ofrece, residencia y categoría del cliente, y canal de distribución. Consulta FSMA para el alcance belga y ESMA para el marco europeo y referencias de supervisión. Conserva enlace, fecha y versión de la información, distinguiendo una advertencia al consumidor de un texto normativo. Si faltan datos sobre la oferta o existe una situación transfronteriza compleja, no deduzcas autorización por la mera existencia de una web accesible. Esta unidad ofrece educación regulatoria con fuentes fechadas; una conclusión sobre un contrato personal requiere revisar sus circunstancias y, cuando proceda, asesoramiento cualificado."),
    ], workedExample: { title: "Exposición hipotética, sin oferta de producto", scenario: "Un ejemplo matemático muestra 1.000 € de margen y exposición de 20.000 €; no representa un producto autorizado en Bélgica.", steps: ["Apalancamiento nocional: 20.000/1.000 = 20 veces.", "Movimiento adverso del 1 % sobre esa exposición: 200 €, antes de costes.", "Pérdida sobre margen inicial: 200/1.000×100 = 20 %. La legalidad no se determina con esa división."], conclusion: "Calcular exposición no prueba autorización de distribución ni garantiza protecciones contractuales." },
    commonMistakes: [{ mistake: "Usar Forex como categoría jurídica única", correction: "Identifica primero el contrato y su forma de negociación." }, { mistake: "Citar ESMA 2018 como única norma vigente en toda situación", correction: "Verifica medidas nacionales actuales y alcance de cliente y producto." }], summary: ["La clasificación del producto precede a la norma.", "La FAQ belga delimita distribución electrónica de derivados OTC.", "Las protecciones no se trasladan automáticamente entre contratos."], relatedConcepts: ["FSMA", "ESMA", "OTC", "Saldo negativo"],
    sources: [
      { title: "FSMA: qué prohíbe el reglamento de distribución", url: "https://www.fsma.be/en/faq/2-what-prohibited-under-regulation", note: "Fuente oficial verificada el 13/10/2026; revisar alcance completo antes de evaluar una oferta concreta." },
      { title: "ESMA: fin de renovación de medidas temporales CFD", url: "https://www.esma.europa.eu/press-news/esma-news/esma-ceases-renewal-product-intervention-measures-relating-contracts", note: "Comunicado de 31/07/2019 sobre transición hacia medidas nacionales." },
      { title: "ESMA: responsabilidad agregada y saldo negativo", url: "https://www.esma.europa.eu/publications-data/questions-answers/1981", note: "Explicación oficial de la protección en el contexto de intervención sobre CFD; no es protección universal para todo instrumento." },
    ], diagram: { title: "Clasificación antes de conclusión", nodes: ["Producto y contraparte", "OTC o mercado organizado", "Cliente y residencia", "Medida nacional aplicable", "Condiciones verificadas"], caption: "Una cotización común no hace equivalentes los contratos ni sus protecciones." },
    questions: [
      { type: "number", concept: "Exposición", prompt: "20.000 € de exposición divididos entre 1.000 € de margen equivalen a ¿cuántas veces?", answer: 20, tolerance: 0, required: true, explanation: "La relación es 20; el cálculo no determina si una oferta concreta está autorizada." },
      { type: "choice", concept: "Alcance FSMA", prompt: "La prohibición específica descrita en la FAQ se refiere a…", options: ["Distribución electrónica a consumidores de determinados derivados OTC", "Todo cambio de moneda para cualquier fin", "Toda simulación educativa sin contrato financiero"], answer: "Distribución electrónica a consumidores de determinados derivados OTC", explanation: "El alcance debe conservar sus condiciones de producto, distribución y destinatario." },
      { type: "boolean", concept: "Protecciones", prompt: "La protección de saldo negativo de un marco CFD se aplica automáticamente a cualquier futuro.", options: ["Verdadero", "Falso"], answer: "Falso", explanation: "No se trasladan protecciones entre instrumentos y categorías sin base aplicable." },
      { type: "text", concept: "Autoridad belga", prompt: "¿Qué siglas identifican a la autoridad citada para comprobar el alcance belga?", answer: "FSMA", explanation: "Sus fuentes oficiales permiten revisar la distribución y verificar proveedores en Bélgica." },
    ],
  }),
  unit({ slug: "verificar-proveedores-y-prevenir-fraudes", title: "Verificar proveedores y prevenir fraudes", subtitle: "Un registro auténtico no autentica automáticamente a quien usa su nombre.",
    objectives: ["Contrastar identidad y autorización", "Detectar suplantaciones y presión comercial", "Preservar pruebas ante una oferta sospechosa"], prerequisites: ["Regulación e instrumentos"],
    sections: [
      section("identidad", "Separar marca, entidad y permiso", "Una oferta puede mostrar una marca conocida, un número de registro y un logotipo de supervisor sin que eso identifique correctamente a quien te contacta. Busca la entidad jurídica por un canal oficial al que accedas de forma independiente. Comprueba qué actividad está autorizada y si corresponde al producto ofrecido; una inscripción para un servicio no equivale a permiso para cualquier inversión. La herramienta de FSMA permite consultar proveedores y advertencias. Guarda resultados y fecha de consulta. La ausencia de una advertencia no demuestra autorización: una oferta nueva o desconocida puede no haber sido investigada todavía."),
      section("clones", "La empresa real y su imitador", "La FSMA describe las empresas clonadas como suplantaciones de entidades autorizadas. El fraude utiliza datos legítimos para parecer regulado, pero cambia dominio, teléfono, correo o instrucciones de pago. Contrasta los datos de contacto con el registro oficial y utiliza esos canales, no los enlaces enviados por la persona que intenta convencerte. Un parecido ortográfico o un certificado adjunto no resuelve una discrepancia. Tampoco basta que una web enlace a una página auténtica del supervisor. La comprobación debe unir identidad, contacto, actividad y oferta; si una de esas piezas no coincide, detén el proceso de verificación antes de transferir información sensible o dinero."),
      section("presion", "Señales comerciales que requieren distancia", "Promesas de rendimientos seguros, urgencia para ingresar, presión tras una negativa o solicitudes de acceso remoto son motivos para parar y comprobar. Una cifra de beneficio mostrada en una pantalla puede ser fabricada y no prueba que exista un activo retirable. Exigir nuevos pagos para liberar supuestas ganancias puede prolongar una pérdida inicial. No interpretes una conversación amable o un grupo con muchos testimonios como sustituto de documentación verificable. En el aprendizaje, practica reconocer la estructura de la presión: reduce tiempo para comprobar, presenta una recompensa desproporcionada y desplaza la decisión desde evidencia hacia miedo a perder una oportunidad."),
      section("respuesta", "Qué conservar y dónde contrastar", "Ante una oferta sospechosa, conserva mensajes, direcciones, documentación y fechas sin continuar entregando credenciales o códigos de acceso. Utiliza canales oficiales de FSMA para consultas y avisos, y los procedimientos pertinentes de denuncia cuando exista un perjuicio. No publiques datos personales innecesarios al explicar el caso. Una persona que promete recuperar fondos a cambio de otra comisión también necesita verificación independiente; haber sufrido una pérdida no hace más fiable una segunda oferta. El propósito no es clasificar automáticamente toda empresa desconocida como fraude, sino mantener un proceso comprobable y no actuar mientras identidad, autorización o condiciones esenciales sigan sin aclararse."),
    ], workedExample: { title: "Comprobación ficticia de identidad", scenario: "Un registro oficial muestra 4 datos de contacto e identificación. Una oferta coincide en nombre y número, pero cambia dominio y teléfono.", steps: ["Coincidencias: 2 de 4 campos.", "Discrepancias: 2 campos relevantes para contactar.", "No se aprueba la oferta con una media del 50 %: se contrasta por el canal oficial."], conclusion: "La identidad no se verifica por votación de campos; una discrepancia crítica exige resolverla." },
    commonMistakes: [{ mistake: "Confiar solo en un número de licencia copiado", correction: "Contrasta entidad, actividad y contacto por canales independientes." }, { mistake: "Tomar ausencia de advertencia como autorización", correction: "Busca evidencia positiva del permiso correspondiente." }], summary: ["Comprueba permiso e identidad por separado.", "Los clones reutilizan datos auténticos.", "La presión no sustituye evidencia."], relatedConcepts: ["Empresa clonada", "Autorización", "Fraude de recuperación"], sources: [
      { title: "FSMA: verificar al proveedor", url: "https://www.fsma.be/en/check-your-provider", note: "Herramienta y recomendaciones oficiales consultadas el 13/10/2026." },
      { title: "FSMA: empresas clonadas", url: "https://www.fsma.be/en/cloned-firms", note: "Explicación oficial de suplantación y contraste de datos de contacto." },
      { title: "FSMA: lista de advertencias", url: "https://www.fsma.be/en/warnings-list-companies-operating-unlawfully-belgium", note: "La ausencia de advertencia no constituye prueba de autorización." },
    ], diagram: { title: "Comprobación independiente", nodes: ["Oferta recibida", "Registro oficial consultado aparte", "Entidad + permiso", "Dominio + contacto", "Resolver discrepancias antes de actuar"], caption: "Nunca uses una coincidencia parcial como sustituto de identidad verificable." },
    questions: [
      { type: "number", concept: "Discrepancias", prompt: "De cuatro campos, dos coinciden. ¿Cuántos quedan discrepantes?", answer: 2, tolerance: 0, required: true, explanation: "4−2=2; los campos críticos no se compensan mediante un porcentaje." },
      { type: "choice", concept: "Clonación", prompt: "¿Qué protege frente a un número de licencia copiado?", options: ["Contrastar dominio y contacto por el registro oficial", "Confiar en el logotipo", "Pagar una cantidad pequeña como prueba"], answer: "Contrastar dominio y contacto por el registro oficial", explanation: "Los clones pueden copiar datos auténticos sin pertenecer a la entidad autorizada." },
      { type: "boolean", concept: "Advertencias", prompt: "Si no hay advertencia publicada, la empresa está necesariamente autorizada.", options: ["Verdadero", "Falso"], answer: "Falso", explanation: "La lista de advertencias no es una lista exhaustiva de todas las ofertas no autorizadas." },
      { type: "text", concept: "Suplantación", prompt: "Una empresa que copia la identidad de otra autorizada se denomina empresa…", answer: "clonada", acceptedAnswers: ["clon"], explanation: "La suplantación aprovecha información legítima para autenticar una oferta que no lo es." },
    ],
  }),
  unit({ slug: "fiscalidad-introductoria-y-registros", title: "Fiscalidad introductoria y mantenimiento de registros", subtitle: "Registrar bien permite formular preguntas fiscales concretas sin inventar reglas generales.",
    objectives: ["Separar cálculo económico y tratamiento fiscal", "Preparar documentación trazable", "Identificar fuentes oficiales belgas pertinentes"], prerequisites: ["Resultados netos y moneda de cuenta"],
    sections: [
      section("distincion", "Beneficio contable y obligación fiscal son preguntas distintas", "Sumar ganancias y pérdidas de un registro no determina por sí solo cuánto tributa una persona. El tratamiento puede depender de residencia fiscal, instrumento, naturaleza de la actividad, periodo y circunstancias individuales. No extrapoles una afirmación sobre acciones a CFD, futuros o remuneraciones contractuales por una simulación. Tampoco supongas que un resultado pequeño, una cuenta extranjera o la ausencia de retirada elimina obligaciones. Esta unidad enseña a organizar información y verificar fuentes; no asigna tipos impositivos ni clasifica una actividad personal. Las reglas pueden cambiar y deben comprobarse para el ejercicio y la situación que realmente se analizan."),
      section("documentos", "Qué información conviene poder reconstruir", "Conserva extractos, operaciones, comisiones, financiación, depósitos, retiradas y conversiones de moneda, junto a identidad de la contraparte y fechas. Distingue transferencias de capital de resultados de inversión: ingresar dinero aumenta el saldo, pero no es beneficio de una operación. Si un informe convierte importes a euros, registra fuente y fecha del tipo aplicado y conserva cantidades originales. No sobrescribas los archivos de origen cuando normalices datos. Un cuadro de conciliación debe explicar cómo se pasa del saldo inicial al final. Esta trazabilidad facilita detectar omisiones y permite a un profesional revisar hechos concretos en lugar de depender de capturas aisladas."),
      section("belgica", "Fuentes y cuentas extranjeras", "Para Bélgica, FPS Finance es la fuente oficial para información tributaria y procedimientos de declaración. La National Bank of Belgium mantiene el Punto de Contacto Central de cuentas y contratos financieros y publica instrucciones sobre comunicación de cuentas extranjeras. Consulta el alcance aplicable a tu titularidad y residencia, además de las obligaciones de la declaración fiscal correspondiente; no confundas un trámite informativo con el cálculo de un impuesto. Una cuenta demo con saldo ficticio no debe confundirse automáticamente con una cuenta bancaria extranjera real, aunque un contrato comercial asociado pueda requerir otras preguntas. Verifica los hechos antes de elegir un formulario o una categoría."),
      section("consulta", "Preparar una consulta útil y mantener registros", "Una consulta concreta identifica año, residencia, producto contractual, entidad, moneda, movimientos y documentos disponibles. Pregunta expresamente qué clasificación y obligaciones corresponden, en lugar de buscar una respuesta universal sobre si el Forex paga impuestos. Conserva la respuesta profesional y las fuentes consultadas con su fecha, sin convertirlas en una regla general para otras personas. Define una rutina de archivo y copias de seguridad; una pérdida del navegador no debería ser la única copia de información necesaria. Separa los registros educativos de datos fiscales reales y evita subir documentos personales a repositorios públicos o servicios que no necesitan conocerlos para corregir ejercicios."),
    ], workedExample: { title: "Conciliación económica simulada, sin cálculo fiscal", scenario: "Saldo inicial 2.000 €, depósito 500 €, ganancias 120 €, pérdidas 70 € y costes 10 €; no hay otras partidas.", steps: ["Resultado económico neto: 120−70−10 = 40 €.", "Saldo final: 2.000+500+40 = 2.540 €.", "El aumento total de saldo es 540 €, pero 500 € son aportación y no beneficio del registro."], conclusion: "Los 40 € son un cálculo económico ficticio; la unidad no determina una base ni una cuota tributaria." },
    commonMistakes: [{ mistake: "Tratar todo aumento de saldo como beneficio", correction: "Separa aportaciones, retiradas y resultados." }, { mistake: "Aplicar a cualquier producto una regla fiscal leída sobre otro", correction: "Identifica contrato, ejercicio y circunstancias antes de consultar." }], summary: ["Economía y fiscalidad no son equivalentes.", "Conserva originales y conversiones.", "Consulta fuentes y obligaciones concretas."], relatedConcepts: ["Residencia fiscal", "Conciliación", "CPC"], sources: [
      { title: "FPS Finance: información para particulares", url: "https://fin.belgium.be/en", note: "Portal oficial belga consultado el 13/10/2026; verificar el ejercicio fiscal y la situación concreta." },
      { title: "NBB: Punto de Contacto Central", url: "https://www.nbb.be/en/central-credit-registers/central-point-contact-accounts-and-financial-contracts-cpc-0", note: "Registro oficial y enlaces a procedimientos. No determina por sí solo la tributación de un resultado." },
      { title: "NBB: comunicación de cuentas extranjeras", url: "https://www.nbb.be/en/central-credit-registers/central-point-contact-accounts-and-financial-contracts-cpc/submission/reporting-foreign-accounts", note: "Instrucciones oficiales indexadas y verificadas el 12/10/2026; consultar alcance y actualizaciones." },
    ], diagram: { title: "Saldo no equivale a beneficio", nodes: ["Inicial 2.000 €", "Aportación +500 €", "Resultado neto +40 €", "Final 2.540 €", "Clasificación fiscal: análisis aparte"], caption: "Ejercicio simulado sin tipos tributarios ni asesoramiento fiscal individual." },
    questions: [
      { type: "number", concept: "Resultado económico", prompt: "120 de ganancias menos 70 de pérdidas y 10 de costes dan ¿cuánto neto?", answer: 40, tolerance: 0, required: true, explanation: "120−70−10=40 €; el depósito de 500 € no es beneficio." },
      { type: "choice", concept: "Registros", prompt: "¿Qué permite explicar un saldo final mayor sin atribuirlo todo a rentabilidad?", options: ["Separar depósitos, retiradas y resultados", "Guardar solo el saldo final", "Eliminar las comisiones"], answer: "Separar depósitos, retiradas y resultados", explanation: "Los movimientos de capital tienen una función distinta de las ganancias o pérdidas." },
      { type: "boolean", concept: "Fiscalidad", prompt: "Una fórmula de beneficio neto determina por sí sola el impuesto de cualquier residente.", options: ["Verdadero", "Falso"], answer: "Falso", explanation: "La clasificación tributaria depende de reglas y circunstancias adicionales." },
      { type: "text", concept: "Fuente oficial", prompt: "¿Qué institución belga citada mantiene el Punto de Contacto Central: FSMA o NBB?", answer: "NBB", acceptedAnswers: ["National Bank of Belgium", "Banco Nacional de Bélgica"], explanation: "NBB mantiene el registro CPC; FPS Finance informa de procedimientos tributarios." },
    ],
  }),
  unit({ slug: "seguridad-copias-y-evaluacion-profesional", title: "Seguridad, copias y evaluación de competencia", subtitle: "La preparación incluye proteger registros y reconocer los límites de lo que has demostrado.",
    objectives: ["Diseñar protección básica de cuentas y datos", "Comprobar una restauración", "Construir un informe de competencias sin prometer rentabilidad"], prerequisites: ["Registros, sistema y prevención de fraude"],
    sections: [
      section("acceso", "Proteger acceso sin depender de una sola barrera", "Utiliza credenciales diferentes para servicios distintos y evita reutilizar la contraseña de tu correo, porque ese correo puede permitir restablecer otros accesos. Un gestor de contraseñas ayuda a mantener valores largos y únicos. Activa autenticación multifactor cuando el servicio la ofrezca, prefiriendo métodos resistentes a phishing si están disponibles y comprendidos. Ninguna medida autoriza compartir códigos con una persona que llama diciendo ser soporte. Accede por direcciones verificadas y revisa solicitudes inesperadas de autorización. La seguridad requiere mantener dispositivos y aplicaciones actualizados, además de proteger credenciales: una contraseña fuerte no corrige un equipo comprometido ni una autorización concedida al destinatario equivocado."),
      section("datos", "Entender dónde vive tu información", "En una aplicación local de navegador, el progreso puede estar ligado al origen, perfil y dispositivo. Borrar datos del sitio, cambiar de navegador o perder el equipo puede hacer que esa copia deje de estar disponible. GitHub Pages aloja archivos estáticos y no sincroniza automáticamente el contenido personal de IndexedDB. Exporta copias cuando quieras conservar o trasladar registros, y guarda los archivos en un lugar apropiado para su sensibilidad. Un repositorio público no es un archivo personal privado. Tampoco incluyas claves de servicios privados en código frontend: cualquier visitante puede inspeccionar el contenido que recibe su navegador."),
      section("restauracion", "Una copia no está comprobada hasta restaurarla", "La existencia de un archivo no garantiza que contenga todos los registros ni que una versión futura pueda leerlo. Comprueba fecha, versión, tamaño y alcance; conserva varias copias según la importancia de los datos. Ensaya una restauración en un entorno separado cuando sea posible, verificando recuentos y muestras de información. Antes de reemplazar datos actuales, previsualiza qué se importará y conserva una copia del estado que vas a sobrescribir. Si el archivo es incompatible, recházalo completo en lugar de aplicar una mitad. La integridad de la restauración es parte del proceso educativo porque resultados perdidos o mezclados destruyen trazabilidad."),
      section("competencia", "Qué significa completar la formación", "Un informe de competencia puede demostrar que explicas productos, calculas riesgo, identificas sesgos, documentas una estrategia y revisas una simulación reproducible. Debe enumerar también contenidos pendientes, errores frecuentes y límites de la evidencia. Una calificación de ejercicios no autoriza prestar servicios regulados ni demuestra rentabilidad futura. Diferencia conocimiento conceptual, ejecución de procedimientos y evaluación estadística; cada dimensión necesita pruebas propias. El siguiente paso puede ser estudiar una debilidad, mejorar un registro o detener una hipótesis inviable. La preparación responsable conserva la capacidad de decir no sé todavía y evita convertir una curva favorable o un certificado educativo en una promesa económica."),
    ], workedExample: { title: "Comprobación simulada de una copia", scenario: "Antes de exportar hay 18 intentos, 6 lecciones completadas y 4 notas. Tras restaurar aparecen 18, 6 y 3 respectivamente.", steps: ["Intentos y lecciones coinciden.", "Falta una nota: 4−3 = 1.", "La restauración no se considera íntegra; se investiga antes de sustituir la única copia válida."], conclusion: "Coincidir en dos recuentos no compensa perder información en un tercero." },
    commonMistakes: [{ mistake: "Confiar en un archivo sin probar su lectura", correction: "Verifica restauración, versión y alcance." }, { mistake: "Llamar rentable a quien aprobó ejercicios", correction: "Describe competencias demostradas y límites de evidencia." }], summary: ["Protege acceso y dispositivos.", "Las copias personales no se sincronizan por alojar la web.", "La competencia educativa no garantiza ingresos."], relatedConcepts: ["MFA", "Restauración", "Competencia demostrada"], sources: [
      { title: "CISA: autenticación multifactor", url: "https://www.cisa.gov/audiences/small-and-medium-businesses/secure-your-business/require-multifactor-authentication", note: "Recomendaciones oficiales de protección de acceso, consultadas el 13/10/2026." },
      { title: "CISA: guía de prevención y recuperación", url: "https://www.cisa.gov/stopransomware/ransomware-guide", note: "Referencia oficial sobre protección, copias y recuperación; el ejercicio de restauración es propio." }, demo,
    ], diagram: { title: "Verificar la portabilidad", nodes: ["18 intentos / 6 lecciones / 4 notas", "Exportar y conservar", "Restaurar aparte", "Comparar recuentos y contenido", "Aceptar solo integridad comprobada"], caption: "El procedimiento comprueba datos, no rentabilidad ni autorización profesional." },
    questions: [
      { type: "number", concept: "Integridad", prompt: "Había 4 notas y se restauran 3. ¿Cuántas faltan?", answer: 1, tolerance: 0, required: true, explanation: "4−3=1; debe investigarse antes de considerar completa la restauración." },
      { type: "choice", concept: "Persistencia local", prompt: "Alojar la web en GitHub Pages implica que el progreso de IndexedDB…", options: ["Sigue siendo local salvo un mecanismo explícito de portabilidad", "Se sincroniza automáticamente entre dispositivos", "Se publica automáticamente en el repositorio"], answer: "Sigue siendo local salvo un mecanismo explícito de portabilidad", explanation: "El alojamiento estático no sincroniza el almacenamiento personal del navegador." },
      { type: "boolean", concept: "Credenciales", prompt: "Una clave privada incluida en código frontend puede mantenerse secreta frente a visitantes.", options: ["Verdadero", "Falso"], answer: "Falso", explanation: "El código y los recursos enviados al navegador son inspeccionables." },
      { type: "text", concept: "Seguridad", prompt: "¿Qué siglas se usan para autenticación con más de un factor?", answer: "MFA", explanation: "Añade factores de verificación, aunque no sustituye prudencia frente a phishing ni protección del dispositivo." },
    ],
  }),
];
